INSERT INTO `news_articles` VALUES (1,'Aligning formulation chemistry with real-world patient adherence','aligning-formulation-chemistry-with-patient-adherence','RESEARCH & FORMULATION','How disciplined formulation design and dosage form engineering reduce treatment complexity across chronic care therapeutic areas.',NULL,'/assets/news-1.jpg','2026-09-07 21:07:34','published',NULL,NULL,NULL,NULL,'2026-09-07 21:07:34','2026-09-07 21:07:34'),(2,'Connecting medical practice insights to therapeutic portfolio depth','connecting-medical-practice-insights-to-portfolio-depth','CLINICAL PRACTICE','Engaging directly with healthcare practitioners to address unmet clinical nuances in paediatric and geriatric patient cohorts.',NULL,'/assets/news-2.jpg','2026-09-07 21:07:34','published',NULL,NULL,NULL,NULL,'2026-09-07 21:07:34','2026-09-07 21:07:34'),(3,'Evaluating material efficiency in pharmaceutical cold-chain and packaging','evaluating-material-efficiency-pharmaceutical-packaging','SUSTAINABILITY','A structured look at reducing secondary material volume while strictly preserving formulation stability and barrier integrity.',NULL,'/assets/news-3.jpg','2026-09-07 21:07:34','published',NULL,NULL,NULL,NULL,'2026-09-07 21:07:34','2026-09-07 21:07:34');
