INSERT INTO `page_sections` VALUES (1,1,'hero','hero','ABOUT ONECORE','Healthcare is personal. Our approach should be too. ','Purposeful formulations. Dependable quality.','Onecore Pharma is a pharmaceutical company focused on purposeful formulations, dependable quality and the needs of patients and healthcare professionals.','[]','Discover Onecore','/about','','','/assets/hero-healthcare.jpg','',1,1,'2026-09-11 07:07:01','2026-09-29 17:38:00'),(2,1,'about_overview','editorial','WHO WE ARE','A pharmaceutical company committed to purposeful formulations.',NULL,'Onecore Pharma operates across key therapeutic disciplines, developing quality medicines with disciplined clinical rigor, patient-first thinking and modern formulation science.',NULL,'Learn About Onecore','/about',NULL,NULL,'/assets/hero-patients-professionals.jpg',NULL,2,1,'2026-09-11 07:07:01','2026-09-15 10:01:02'),(3,1,'areas_of_care','cards_grid','AREAS OF CARE','Focused expertise. Purposeful healthcare.',NULL,'Our specialized divisions deliver focused therapies across major medical fields.',NULL,'Explore','/areas-of-care',NULL,NULL,NULL,NULL,2,1,'2026-09-11 07:07:01','2026-09-15 18:16:47'),(4,1,'our_purpose','vision_mission','OUR PURPOSE','Improve care through medicines and healthcare solutions that matter.',NULL,NULL,'[{\"title\":\"OUR VISION\",\"desc\":\"To be a trusted pharmaceutical company for patients and healthcare professionals across the areas of care we serve.\"},{\"title\":\"OUR MISSION\",\"desc\":\"To develop and deliver purposeful formulations that address real clinical needs, uphold dependable quality and expand responsibly into areas where we can make a meaningful difference.\"}]',NULL,NULL,NULL,NULL,NULL,NULL,3,1,'2026-09-11 07:07:01','2026-09-15 18:16:47'),(5,1,'quality_dark','quality_highlight','QUALITY ASSURANCE','Quality is part of the product from the beginning.',NULL,'Medicines carry responsibility. That is why quality needs to be considered across manufacturing, testing, review and release, not treated as a final checkpoint.',NULL,'Quality Standards','/quality-manufacturing',NULL,NULL,'/assets/quality.jpg',NULL,5,1,'2026-09-11 07:07:01','2026-09-11 07:07:01'),(6,1,'sustainability','features_columns','SUSTAINABILITY','Better health and a healthier future belong together.',NULL,'Our responsibility extends beyond the products we provide. As Onecore grows, we want responsible choices to become part of how we operate, how we source and how we work with our partners.','[{\"eyebrow\":\"RESPONSIBLE OPERATIONS\",\"title\":\"Use resources thoughtfully.\",\"desc\":\"Work toward more efficient use of energy, water and materials across the operations and manufacturing network that support our products.\",\"icon\":\"Cpu\"},{\"eyebrow\":\"PACKAGING\",\"title\":\"Reduce what is unnecessary.\",\"desc\":\"Evaluate packaging choices with the aim of reducing avoidable material use while protecting product quality, safety and stability.\",\"icon\":\"Leaf\"},{\"eyebrow\":\"RESPONSIBLE PARTNERSHIPS\",\"title\":\"Grow with shared standards.\",\"desc\":\"Build relationships with partners who share expectations around quality, compliance, ethical conduct and environmental responsibility.\",\"icon\":\"Users\"}]',NULL,NULL,NULL,NULL,NULL,NULL,5,1,'2026-09-11 07:07:01','2026-09-15 18:16:47'),(7,1,'looking_ahead','timeline_list','LOOKING AHEAD','Building depth. \nExpanding thoughtfully.',NULL,'Our roadmap prioritizes therapeutic rigor, medical dialogue, and disciplined expansion that preserves trust.','[{\"title\":\"Deepen therapeutic expertise\",\"desc\":\"Build stronger portfolios within our core areas of care.\"},{\"title\":\"Strengthen medical engagement\",\"desc\":\"Stay closer to clinical practice and evolving healthcare needs.\"},{\"title\":\"Expand thoughtfully\",\"desc\":\"Enter new areas where the portfolio can add meaningful value.\"},{\"title\":\"Grow responsibly\",\"desc\":\"Strengthen quality, partnerships and sustainable practices as the organisation scales.\"}]',NULL,NULL,NULL,NULL,NULL,NULL,6,1,'2026-09-11 07:07:01','2026-09-15 18:16:47'),(8,1,'final_cta','cta_banner',NULL,'Purposeful healthcare, across every area we serve.',NULL,'Explore the therapeutic areas and formulations that make up the Onecore portfolio.',NULL,'Explore areas of care','/areas-of-care','Connect With Us','/contact',NULL,NULL,8,1,'2026-09-11 07:07:01','2026-09-15 18:16:47'),(9,5,'hero','hero','QUALITY & MANUFACTURING','Quality built into every stage of the product journey.',NULL,'At Onecore Pharma, quality is not treated as a final checkpoint. It is considered throughout the product journey, from formulation and sourcing to manufacturing, testing and responsible release.',NULL,'Quality Principles','#principles','Explore Specialties','/areas-of-care','/assets/quality.jpg',NULL,1,1,'2026-09-11 07:07:01','2026-09-15 18:16:47'),(10,5,'commitment','editorial','OUR COMMITMENT','Quality is part of the product from the beginning.',NULL,'Our approach to quality is built around consistent standards, careful processes and responsible decision-making. We work to ensure that the products we bring to patients and healthcare professionals meet the standards expected of a responsible pharmaceutical company.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,2,1,'2026-09-11 07:07:01','2026-09-11 07:07:01'),(11,5,'manufacturing_excellence','editorial_split','MANUFACTURING EXCELLENCE','Manufacturing with discipline and control.',NULL,'Our manufacturing approach is focused on controlled processes, reliable sourcing and appropriate quality oversight. We work with manufacturing partners and systems that support the standards expected across our portfolio.',NULL,NULL,NULL,NULL,NULL,'/assets/hero-healthcare.jpg',NULL,3,1,'2026-09-11 07:07:01','2026-09-11 07:07:01'),(12,5,'final_cta','cta_banner',NULL,'Quality you can depend on.',NULL,'Explore the therapeutic areas and formulations that make up the Onecore portfolio.',NULL,'Explore Areas of Care','/areas-of-care','Contact Quality Team','/contact',NULL,NULL,5,1,'2026-09-11 07:07:01','2026-09-15 18:16:47'),(13,2,'hero','hero','ABOUT ONECORE','Purposeful formulations. Dependable quality. Patient-centered care.',NULL,'Onecore Pharma is built around the belief that modern pharmaceutical science achieves its highest impact when aligned closely with the clinical reality of patients and doctors.',NULL,NULL,NULL,NULL,NULL,'/assets/about-video-poster.jpg',NULL,1,1,'2026-09-11 07:07:01','2026-09-15 18:16:47'),(30,1,'quality_assurance','quality_highlight','QUALITY ASSURANCE','Quality is part of the product from the beginning.','Our approach is centered on qualified manufacturing environments, appropriate quality controls and disciplined review before products reach the market.','Medicines carry responsibility. That is why quality needs to be considered across manufacturing, testing, review and release, not treated as a final checkpoint.','[{\"title\":\"Consistent standards\",\"desc\":\"Quality expectations aligned to the nature and regulatory requirements of each product.\"},{\"title\":\"Responsible release\",\"desc\":\"Review and controls designed to support product consistency and reliability.\"}]','Quality Standards','/quality-manufacturing',NULL,NULL,'/assets/quality.jpg',NULL,4,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(33,1,'news_preview','editorial','LATEST FROM ONECORE','News & perspectives.',NULL,NULL,NULL,'View all news','/news',NULL,NULL,NULL,NULL,7,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(36,2,'foundation','editorial_split','OUR FOUNDATION','Our Foundation & Vision',NULL,'At Onecore Pharma, every formulation starts with a distinct clinical question: How can this medicine make treatment more reliable, accessible, and comfortable for the patient?\n\nWe bring together rigorous research, disciplined quality oversight, and ethical supply chain standards across multi-therapeutic disciplines to serve patients and clinicians with dependable healthcare solutions.','[{\"stat\":\"09+\",\"title\":\"Therapeutic Specialties\",\"desc\":\"Comprehensive portfolio addressing clinical nuances across essential therapeutic categories.\"},{\"stat\":\"100%\",\"title\":\"Quality Release Protocol\",\"desc\":\"Multi-tier analytical verification and strict batch release authorization before clinical distribution.\"}]',NULL,NULL,NULL,NULL,'/assets/about-facility.jpg',NULL,2,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(37,2,'principles','cards_grid','FOUNDATIONAL PRINCIPLES','Principles guiding every decision.','A disciplined framework connecting formulation science with clinical trust and everyday care.',NULL,'[{\"title\":\"Clinical Relevance\",\"description\":\"Focusing formulation research on real-world medical challenges and patient comfort.\",\"detail\":\"Aligning active pharmaceutical ingredients and delivery formats with physician feedback and daily regimen realities.\"},{\"title\":\"Uncompromising Quality\",\"description\":\"Treating quality as an intrinsic requirement from raw material intake to final market release.\",\"detail\":\"Adhering to strict cGMP parameters, validated analytical testing, and comprehensive batch traceability.\"},{\"title\":\"Responsible Stewardship\",\"description\":\"Building lasting partnerships and adopting sustainable manufacturing standards.\",\"detail\":\"Committed to ethical commercial practices, continuous pharmacovigilance, and long-term healthcare integrity.\"}]',NULL,NULL,NULL,NULL,NULL,NULL,3,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(38,2,'commitments','cards_grid','OUR COMMITMENTS','Disciplined science, human focus.','Connecting clinical insight with dependable pharmaceutical manufacturing to deliver medicines people can trust.',NULL,'[{\"title\":\"Therapeutic Breadth\",\"text\":\"Developing specialized portfolios across essential medical disciplines including General Medicine, Paediatrics, ENT, Orthopaedics, and Oncology.\",\"icon\":\"Layers\"},{\"title\":\"Formulation Integrity\",\"text\":\"Every batch is verified through rigorous stability testing, identity verification, and multi-stage analytical checkpoints.\",\"icon\":\"ShieldCheck\"},{\"title\":\"Patient Centricity\",\"text\":\"Creating clear, transparent product information and reliable supply chains to support continuity in everyday care.\",\"icon\":\"HeartPulse\"}]',NULL,NULL,NULL,NULL,NULL,NULL,4,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(39,2,'final_cta','cta_banner',NULL,'Explore our therapeutic specialties and quality disciplines.',NULL,'Discover how our formulations serve diverse clinical disciplines with dependable consistency.',NULL,'Areas of Care','/areas-of-care','Quality Standards','/quality-manufacturing',NULL,NULL,5,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(40,3,'hero','hero','PATIENTS & PROFESSIONALS','For the people receiving care. \nAnd the people providing it.',NULL,'Patients live the experience of a health condition. Healthcare professionals bring the knowledge and judgement needed to manage it.\n\nAt Onecore, both perspectives matter. Our role is to support them with dependable products, clear information and responsible communication.',NULL,'For patients','#for-patients','For healthcare professionals','#for-professionals','/assets/hero-patients-professionals.jpg',NULL,1,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(41,3,'two_perspectives','editorial_split','TWO PERSPECTIVES','Different experiences. \nThe same goal.',NULL,'Good healthcare depends on understanding both the person living with a condition and the professional responsible for treating it.\n\nWe want Onecore to stay close to both. That means listening to patient needs, respecting clinical practice and making sure our products and information remain relevant to real healthcare.',NULL,NULL,NULL,NULL,NULL,'/assets/two-perspectives.jpg',NULL,2,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(42,3,'our_role','cards_grid','OUR ROLE','Listen carefully. \nSupport responsibly. \nKeep the person behind the medicine in view.',NULL,NULL,'[{\"title\":\"See the person, not only the condition.\",\"desc\":\"The experience of living with illness or managing treatment can shape what patients need from healthcare.\",\"footer\":\"Patient lived experience\"},{\"title\":\"Value clinical judgement.\",\"desc\":\"Healthcare professionals bring scientific knowledge and practical experience to every treatment decision.\",\"footer\":\"Evidence & clinical practice\"},{\"title\":\"Make information easier to access.\",\"desc\":\"Patients and professionals should be able to find clear factual information about the products they use or prescribe.\",\"footer\":\"Factual product transparency\"}]',NULL,NULL,NULL,NULL,NULL,NULL,3,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(43,3,'for_patients','editorial_split','FOR PATIENTS AND CAREGIVERS','You should be able to understand the medicines that are part of your care.',NULL,'Clear information helps patients and caregivers take a more informed role in the treatment journey.\n\nOnecore provides factual information about its products and encourages patients to speak with their doctor or pharmacist when they have questions about their individual treatment.','[{\"title\":\"FIND INFORMATION ABOUT YOUR MEDICINE\",\"desc\":\"Access product names, compositions, dosage forms and other factual product information.\"},{\"title\":\"USE MEDICINES RESPONSIBLY\",\"desc\":\"Follow the instructions provided by your healthcare professional and the information supplied with your medicine.\"},{\"title\":\"SHARE SAFETY CONCERNS\",\"desc\":\"Report a suspected side effect or product quality concern involving a Onecore product.\"}]','Product information','/areas-of-care','Report a concern','#patient-safety','/assets/patients-caregivers.jpg',NULL,4,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(44,3,'for_professionals','cards_grid','FOR HEALTHCARE PROFESSIONALS','Supporting clinical practice with clear product information.',NULL,'Healthcare professionals make treatment decisions by bringing together science, clinical experience and the needs of each individual patient.\n\nOur responsibility is to make accurate product information accessible and to maintain clear channels for safety and quality reporting.','[{\"title\":\"Onecore medicines\",\"desc\":\"Access compositions, dosage forms and factual information across the Onecore product portfolio.\",\"cta_text\":\"View product information\",\"cta_url\":\"/areas-of-care\"},{\"title\":\"Professional resources\",\"desc\":\"Access approved prescribing and product information where available for Onecore medicines.\",\"cta_text\":\"View professional resources\",\"cta_url\":\"#prescribing-modal\"},{\"title\":\"Safety reporting\",\"desc\":\"Report suspected adverse reactions or product quality concerns involving Onecore products.\",\"cta_text\":\"Report safety information\",\"cta_url\":\"#patient-safety\"}]',NULL,NULL,NULL,NULL,'/assets/healthcare-professionals.jpg',NULL,5,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(45,3,'treatment_journey','timeline_list','THE TREATMENT JOURNEY','A prescription begins in the clinic. \nCare continues beyond it.',NULL,'Healthcare professionals make treatment decisions in the clinical setting. Patients then carry those decisions into everyday life.\n\nWe believe a responsible pharmaceutical company should understand both parts of that journey and support them with medicines and information people can depend on.','[{\"num\":\"01\",\"title\":\"Healthcare professional\",\"desc\":\"Clinical assessment, diagnosis and evidence-based therapeutic evaluation.\"},{\"num\":\"02\",\"title\":\"Treatment decision\",\"desc\":\"Selecting appropriate formulation, dosage schedule and treatment guidance.\"},{\"num\":\"03\",\"title\":\"Patient\",\"desc\":\"Understanding administration instructions, storage conditions and safety facts.\"},{\"num\":\"04\",\"title\":\"Everyday care\",\"desc\":\"Managing treatment adherence and monitoring recovery in home routine.\"}]',NULL,NULL,NULL,NULL,'/assets/treatment-journey.jpg',NULL,6,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(46,3,'patient_safety','cards_grid','PATIENT SAFETY','Safety information deserves a clear way to reach us.','For medical emergencies, patients should seek immediate medical attention from an appropriate healthcare service.','If a patient, caregiver or healthcare professional becomes aware of a suspected side effect or product quality concern involving a Onecore product, that information can be reported for appropriate review.','[{\"eyebrow\":\"PATIENTS AND CAREGIVERS\",\"title\":\"Report a concern\",\"desc\":\"Tell us about a suspected side effect or quality concern involving a Onecore product.\",\"cta_text\":\"Patient reporting\",\"modal_type\":\"patient\"},{\"eyebrow\":\"HEALTHCARE PROFESSIONALS\",\"title\":\"Report safety information\",\"desc\":\"Submit suspected adverse event or product quality information for appropriate review.\",\"cta_text\":\"Professional reporting\",\"modal_type\":\"professional\"}]',NULL,NULL,NULL,NULL,NULL,NULL,7,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(47,3,'final_cta','cta_banner','ONECORE SUPPORT','Here for the people who use our medicines and the professionals who care for them.',NULL,'Find product information, access professional resources or report a safety or quality concern.',NULL,'Contact Onecore','/contact',NULL,NULL,NULL,NULL,8,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(49,5,'principles','cards_grid','FOUNDATIONAL PRINCIPLES','Principles that guide our quality approach.',NULL,'A disciplined commitment to patient safety, regulatory compliance, and formulation excellence across every batch.','[{\"title\":\"Consistent Standards\",\"desc\":\"Quality begins with clear specifications, controlled processes and consistent standards across the product lifecycle.\"},{\"title\":\"Responsible Release\",\"desc\":\"Products are released only after the appropriate quality requirements and checks have been completed.\"},{\"title\":\"Controlled Processes\",\"desc\":\"Manufacturing and quality processes are designed to support consistency, traceability and dependable product performance.\"},{\"title\":\"Continuous Improvement\",\"desc\":\"We continuously look for opportunities to strengthen processes, improve reliability and support better quality outcomes.\"}]',NULL,NULL,NULL,NULL,NULL,NULL,2,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(50,5,'manufacturing_standards','editorial_split','MANUFACTURING DISCIPLINES','Manufacturing with discipline and control.',NULL,'Onecore formulations are produced in qualified manufacturing environments adhering strictly to cGMP and regulatory standards.','[{\"title\":\"Validated Processes\",\"desc\":\"Equipment calibration and environmental monitoring.\"},{\"title\":\"Batch Traceability\",\"desc\":\"End-to-end documentation across the supply chain.\"}]',NULL,NULL,NULL,NULL,'/assets/hero-healthcare.jpg',NULL,3,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(51,5,'assurance_steps','cards_grid','QUALITY ASSURANCE','Controls throughout the lifecycle.','Key assurance stages designed to support formulation reliability from raw ingredient selection to clinical availability.',NULL,'[{\"title\":\"Raw material and supplier oversight\",\"desc\":\"Disciplined evaluation and verification of starting materials, active pharmaceutical ingredients and qualified supply partners.\"},{\"title\":\"Defined specifications\",\"desc\":\"Clear chemical, physical and stability benchmarks established for every formulation across its shelf life.\"},{\"title\":\"Manufacturing process controls\",\"desc\":\"Structured in-process monitoring and calibrated equipment parameters designed to ensure batch consistency.\"},{\"title\":\"Testing and quality checks\",\"desc\":\"Rigorous analytical and microbiological testing conducted to verify identity, purity, potency and dosage uniformity.\"},{\"title\":\"Documentation and traceability\",\"desc\":\"Complete batch records, systematic tracking and full audit trails maintained throughout production and storage.\"},{\"title\":\"Responsible product release\",\"desc\":\"Independent quality review and systematic verification before any product batch is authorized for clinical distribution.\"}]',NULL,NULL,NULL,NULL,NULL,NULL,4,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(53,7,'hero','hero','CONTACT ONECORE','Start a conversation with Onecore.',NULL,'Whether you are looking for product information, exploring a business opportunity or simply want to reach our team, we will help direct your enquiry to the appropriate place.',NULL,'Send an Enquiry','#enquiry-form','Contact Details','#contact-details','/assets/patients-caregivers.jpg',NULL,1,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(54,7,'direct_channels','cards_grid','GET IN TOUCH','Contact','We’d love to hear from you. Whether you’re a healthcare professional interested in our products or a patient seeking more information, reach out to us',NULL,'[{\"channel\":\"EMAIL\",\"value\":\"info@onecorepharma.in\",\"desc\":\"For general company and product related enquiries.\",\"cta_text\":\"Write to info desk\",\"cta_url\":\"mailto:info@onecorepharma.in\"},{\"channel\":\"PHONE\",\"value\":\"8169255034\",\"desc\":\"Available during business hours.\",\"cta_text\":\"Call our team\",\"cta_url\":\"tel:8169255034\"},{\"channel\":\"BUSINESS HOURS\",\"value\":\"10 AM to 7 PM\",\"desc\":\"For enquiries handled by the Onecore team.\",\"cta_text\":\"WORKING DAYS // MON – SAT\",\"cta_url\":null}]',NULL,NULL,NULL,NULL,NULL,NULL,2,1,'2026-09-15 18:16:47','2026-09-28 18:35:57'),(55,7,'enquiry_types','timeline_list','HOW CAN WE HELP?','Choose the reason for getting in touch.','Selecting the right enquiry type helps your message reach the relevant Onecore team.',NULL,'[{\"num\":\"01\",\"title\":\"Product information\",\"description\":\"For factual information about Onecore products, compositions and available dosage forms.\",\"value\":\"Product information\"},{\"num\":\"02\",\"title\":\"Business & distribution\",\"description\":\"For distribution, institutional supply and other commercial partnership discussions.\",\"value\":\"Business and distribution\"},{\"num\":\"03\",\"title\":\"Careers\",\"description\":\"For opportunities to work with Onecore and career related communication.\",\"value\":\"Careers\"},{\"num\":\"04\",\"title\":\"General enquiries\",\"description\":\"For company related questions that do not fall into another category.\",\"value\":\"General enquiry\"}]',NULL,NULL,NULL,NULL,NULL,NULL,3,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(56,7,'form_intro','editorial','SEND AN ENQUIRY','Tell us how we can help.','Please do not use this form for medical emergencies or to request individual diagnosis, treatment or changes to prescribed medicines. For personal medical advice, contact a qualified healthcare professional.','Complete the form and your enquiry can be directed to the appropriate team.',NULL,'Submit enquiry',NULL,NULL,NULL,NULL,NULL,4,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(57,7,'patient_safety','cards_grid','PATIENT SAFETY','Reporting a safety or quality concern?','Use the dedicated safety reporting route.','Suspected side effects and product quality concerns should be reported through the appropriate safety channel so the information can be reviewed correctly.','[{\"eyebrow\":\"PATIENTS & CAREGIVERS\",\"title\":\"Patient safety reporting\",\"description\":\"Submit observations regarding side effects or product quality issues directly to our pharmacovigilance team.\",\"cta_text\":\"Report a safety or product quality concern\",\"cta_url\":\"/patients-caregivers#patient-safety\"},{\"eyebrow\":\"HEALTHCARE PROFESSIONALS\",\"title\":\"Clinical safety desk\",\"description\":\"Medical practitioners can log adverse drug observations or quality documentation for formal regulatory evaluation.\",\"cta_text\":\"Submit safety information\",\"cta_url\":\"/patients-caregivers#patient-safety\"}]',NULL,NULL,NULL,NULL,NULL,NULL,5,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(58,7,'process_steps','timeline_list','WHAT HAPPENS NEXT','Your message goes to the team best placed to respond.',NULL,NULL,'[{\"num\":\"01\",\"stage\":\"STAGE 1\",\"title\":\"01 — Submit\",\"desc\":\"Tell us who you are and the nature of your enquiry.\"},{\"num\":\"02\",\"stage\":\"STAGE 2\",\"title\":\"02 — Route\",\"desc\":\"Your message is directed to the relevant Onecore function.\"},{\"num\":\"03\",\"stage\":\"STAGE 3\",\"title\":\"03 — Respond\",\"desc\":\"The appropriate team can contact you if a response or further information is required.\"}]',NULL,NULL,NULL,NULL,NULL,NULL,6,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(59,7,'final_cta','cta_banner','ONECORE PHARMA','Healthcare centered on people.',NULL,NULL,NULL,'Explore Onecore','/about',NULL,NULL,NULL,NULL,7,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(60,22,'hero','hero','NEWS & PERSPECTIVES','Insights, clinical updates and formulation perspectives.',NULL,'Stay updated with therapeutic breakthroughs, clinical partnership highlights, and sustainable manufacturing practices from Onecore Pharma.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(61,6,'hero','hero','THERAPEUTIC AREAS','Healthcare needs are different. \nSo are the solutions they require.',NULL,'Explore the areas of care represented across the Onecore portfolio and discover the medicines and formulations within each specialty.',NULL,NULL,NULL,NULL,NULL,'/assets/therapeutic-hero.jpg',NULL,1,1,'2026-09-15 18:16:47','2026-09-15 18:16:47'),(62,6,'portfolio_intro','editorial','OUR PORTFOLIO','Explore by area of care.',NULL,'Choose a specialty to discover the Onecore products and formulations within that area.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,2,1,'2026-09-15 18:16:47','2026-09-15 18:16:47');
