INSERT INTO `pages` VALUES (1,'home','Home','/','published','Onecore Pharma — Purposeful Formulations, Dependable Quality','Onecore Pharma is a modern pharmaceutical company developing purposeful formulations and healthcare solutions centered on patients and healthcare professionals.','2026-09-11 07:07:01','2026-09-11 07:07:01'),(2,'about','About Onecore','/about','published','About Us | Onecore Pharma','Learn about Onecore Pharma, our foundational principles, disciplined pharmaceutical development and commitment to dependable healthcare.','2026-09-11 07:07:01','2026-09-11 07:07:01'),(3,'patients-caregivers','Patients & Caregivers','/patients-caregivers','published','Patients & Caregivers | Onecore Pharma','Resources and factual medicine information for patients and caregivers navigating treatment with Onecore formulations.','2026-09-11 07:07:01','2026-09-11 07:07:01'),(4,'healthcare-professionals','Healthcare Professionals','/healthcare-professionals','published','Healthcare Professionals | Onecore Pharma','Scientific information, clinical dialogue and medical data for doctors and healthcare professionals.','2026-09-11 07:07:01','2026-09-11 07:07:01'),(5,'quality-manufacturing','Quality & Manufacturing','/quality-manufacturing','published','Quality & Manufacturing | Onecore Pharma','Quality built into every stage of the product journey at Onecore Pharma. Controlled processes, dependable standards and responsible release.','2026-09-11 07:07:01','2026-09-11 07:07:01'),(6,'areas-of-care','Therapeutic Areas','/areas-of-care','published','Therapeutic Areas | Onecore Pharma','Explore the therapeutic areas and healthcare needs represented across the Onecore Pharma portfolio.','2026-09-11 07:07:01','2026-09-11 07:07:01'),(7,'contact','Contact','/contact','published','Contact Us | Onecore Pharma','Get in touch with Onecore Pharma for product information, business and distribution enquiries, careers and general company communication.','2026-09-11 07:07:01','2026-09-11 07:07:01'),(22,'news','News & Perspectives','/news','published','News & Perspectives | Onecore Pharma','Insights, clinical updates and formulation perspectives from Onecore Pharma.','2026-09-15 18:16:47','2026-09-15 18:16:47');
