8:53:36'),(561,61,'nortriptyline 10 mg',NULL,'',2,'2026-09-28 18:53:36','2026-09-28 18:53:36'),(562,61,'methylcobalamin 1500 mcg tablets',NULL,'',3,'2026-09-28 18:53:36','2026-09-28 18:53:36'),(563,62,'Lactulose 100 g/15 mL syrup',NULL,'',1,'2026-09-28 18:53:36','2026-09-28 18:53:36'),(564,63,'Sucralfate 1 g',NULL,'',1,'2026-09-28 18:53:36','2026-09-28 18:53:36'),(565,63,'oxetacaine 20 mg suspension',NULL,'',2,'2026-09-28 18:53:36','2026-09-28 18:53:36'),(566,64,'Probiotics (2.5 billion cells)',NULL,'',1,'2026-09-28 18:53:36','2026-09-28 18:53:36'),(567,64,'prebiotic softgel capsules',NULL,'',2,'2026-09-28 18:53:36','2026-09-28 18:53:36'),(568,65,'Rabeprazole sodium 20 mg tablets & injection',NULL,'',1,'2026-09-28 18:53:36','2026-09-28 18:53:36'),(569,66,'Rabeprazole 20 mg',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(570,66,'domperidone 30 mg SR capsules',NULL,'',2,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(571,67,'Rabeprazole 20 mg',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(572,67,'levosulpiride 75 mg SR capsules',NULL,'',2,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(573,68,'Rabeprazole 20 mg',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(574,68,'itopride 150 mg SR capsules',NULL,'',2,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(575,69,'Pantoprazole 40 mg tablets & injection',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(576,70,'Pantoprazole 40 mg',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(577,70,'domperidone 30 mg SR capsules',NULL,'',2,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(578,71,'Myo-inositol',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(579,71,'Tribulus terrestris extract',NULL,'',2,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(580,71,'Ecklonia bicyclis (brown algae)',NULL,'',3,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(581,71,'chitosan oligosaccharides tablets',NULL,'',4,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(582,72,'Cefuroxime 250 mg',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(583,73,'Cefuroxime 500 mg',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(584,74,'Cefuroxime',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(585,74,'clavulanate',NULL,'',2,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(586,30,'Bilastine 20 mg',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(587,30,'montelukast 10 mg tablets',NULL,'',2,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(588,42,'Ondansetron mouth-dissolving 4 mg tablets',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(589,308,'Specialized high-protein nutritional supplement with glutamine, EPA, DHA, antioxidants and essential micronutrients',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(590,309,'Ondansetron 4 mg orally disintegrating tablets',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(591,310,'Ondansetron 8 mg orally disintegrating tablets',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(592,311,'Filgrastim 300 mcg / 0.5 mL solution for injection (Recombinant Human G-CSF)',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(593,312,'Aprepitant 125 mg (Day 1)',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(594,312,'80 mg (Days 2 & 3) capsules',NULL,'',2,'2026-09-28 18:53:37','2026-09-28 18:53:37'),(595,313,'Palonosetron hydrochloride 0.25 mg / 5 mL IV injection',NULL,'',1,'2026-09-28 18:53:37','2026-09-28 18:53:37');
