INSERT INTO `product_safety_sections` VALUES (1,2,'precaution_1','Safety Consideration 1','Curcumin may increase bleeding tendency with anticoagulants/antiplatelets and may cause GI upset.',1,'2026-09-18 06:12:49','2026-09-18 06:12:49'),(2,2,'precaution_2','Safety Consideration 2','CoQ10 may modestly lower blood pressure and can interact with warfarin.',2,'2026-09-18 06:12:49','2026-09-18 06:12:49'),(3,2,'precaution_3','Safety Consideration 3','During active cancer therapy, the oncologist should approve antioxidant supplements.',3,'2026-09-18 06:12:49','2026-09-18 06:12:49'),(4,3,'precaution_1','Safety Consideration 1','Monitor complete blood count and liver function before each treatment cycle.',1,'2026-09-18 06:12:49','2026-09-18 06:12:49'),(5,3,'precaution_2','Safety Consideration 2','Watch for infusion-related hypersensitivity reactions and peripheral neuropathy.',2,'2026-09-18 06:12:49','2026-09-18 06:12:49'),(6,3,'precaution_3','Safety Consideration 3','Avoid use during pregnancy; effective contraception is required during treatment.',3,'2026-09-18 06:12:49','2026-09-18 06:12:49'),(7,3,'precaution_4','Safety Consideration 4','Report fever, signs of infection, severe numbness or tingling promptly.',4,'2026-09-18 06:12:49','2026-09-18 06:12:49'),(8,4,'precaution_1','Safety Consideration 1','Can cause myelosuppression, infection, fever, liver abnormalities, lung toxicity and rarely haemolytic-uraemic syndrome.',1,'2026-09-18 06:12:49','2026-09-18 06:12:49'),(9,4,'precaution_2','Safety Consideration 2','Avoid use during pregnancy.',2,'2026-09-18 06:12:49','2026-09-18 06:12:49'),(10,5,'precaution_1','Safety Consideration 1','Key risks are acute cold-triggered neuropathy, cumulative sensory neuropathy, myelosuppression and infusion reactions.',1,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(11,5,'precaution_2','Safety Consideration 2','Avoid cold drinks/exposure around infusion; monitor renal function and pregnancy status.',2,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(12,6,'precaution_1','Safety Consideration 1','Monitor blood pressure and urine protein regularly.',1,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(13,6,'precaution_2','Safety Consideration 2','Use caution in patients with bleeding, thrombosis or gastrointestinal perforation risk.',2,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(14,6,'precaution_3','Safety Consideration 3','Treatment is generally withheld around major surgery because wound healing may be impaired.',3,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(15,6,'precaution_4','Safety Consideration 4','Avoid use during pregnancy; effective contraception is required during treatment.',4,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(16,7,'precaution_1','Safety Consideration 1','Monitor complete blood count because neutropenia and thrombocytopenia can occur.',1,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(17,7,'precaution_2','Safety Consideration 2','Nausea, fatigue and infection risk are common; antiemetic support may be required.',2,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(18,7,'precaution_3','Safety Consideration 3','Pneumocystis jirovecii pneumonia prophylaxis may be required during concurrent chemoradiation.',3,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(19,7,'precaution_4','Safety Consideration 4','Avoid use during pregnancy; effective contraception is required during treatment.',4,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(20,8,'precaution_1','Safety Consideration 1','Bone pain is common.',1,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(21,8,'precaution_2','Safety Consideration 2','Rare but serious events include splenic rupture, acute respiratory distress, severe allergic reactions and leukocytosis.',2,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(22,8,'precaution_3','Safety Consideration 3','CBC monitoring is required.',3,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(23,9,'precaution_1','Safety Consideration 1','Botanical extracts can interact with anticoagulants, sedatives and other medicines.',1,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(24,9,'precaution_2','Safety Consideration 2','Avoid making anticancer efficacy claims without product-specific clinical evidence; obtain oncologist approval during chemotherapy/radiotherapy.',2,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(25,10,'precaution_1','Safety Consideration 1','High vitamin E/tocotrienol intake may increase bleeding risk with anticoagulants/antiplatelets.',1,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(26,10,'precaution_2','Safety Consideration 2','Use caution before surgery and during active oncology treatment unless the treating team agrees.',2,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(56,24,'precaution_1','Safety Consideration 1','Nosebleeds and irritation are common.',1,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(57,24,'precaution_2','Safety Consideration 2','Monitor growth with prolonged paediatric use and consider systemic steroid effects with high exposure or strong CYP3A4 inhibitors.',2,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(60,26,'precaution_1','Safety Consideration 1','Usually very safe; use a clean nozzle and do not share bottles.',1,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(61,26,'precaution_2','Safety Consideration 2','Persistent unilateral blockage, bleeding or pain requires assessment.',2,'2026-09-18 06:12:50','2026-09-18 06:12:50'),(181,75,'precaution_1','Safety Consideration 1','Counsel about mood, sleep or behavioural changes associated with montelukast.',1,'2026-09-18 06:12:51','2026-09-18 06:12:51'),(182,75,'precaution_2','Safety Consideration 2','Bilastine is usually non-sedating but caution is still sensible when first used.',2,'2026-09-18 06:12:51','2026-09-18 06:12:51'),(183,76,'precaution_1','Safety Consideration 1','Can prolong QT, especially with electrolyte abnormalities or other QT-prolonging drugs.',1,'2026-09-18 06:12:51','2026-09-18 06:12:51'),(184,76,'precaution_2','Safety Consideration 2','Caution with congenital long-QT syndrome and se