INSERT INTO `therapeutic_areas` VALUES (1,'Women’s Health','womens-health','01','Supporting women through different stages of care.','Our women’s health portfolio brings together prescription medicines and supportive formulations across reproductive health, fertility, pregnancy related nutrition, gynaecological care and intimate health.','/assets/therapeutic-womens-health.jpg',1,1,NULL,NULL,'2026-09-07 21:07:34','2026-09-07 21:07:34'),(2,'Paediatrics','paediatrics','02','Care designed around the needs of growing children.','A portfolio spanning paediatric therapeutic and nutritional needs, with formulations and dosage formats suited to different stages of childhood care.','/uploads/pediatrics-1789466876121-797136048.jpg',2,1,NULL,NULL,'2026-09-07 21:07:34','2026-09-15 10:08:02'),(3,'Orthopaedics','orthopaedics','03','Supporting movement, mobility and musculoskeletal care.','Our orthopaedic portfolio spans joint health, bone health, mobility, pain management and musculoskeletal support.','/uploads/orthopaedics-1789467702797-389233258.jpg',3,1,NULL,NULL,'2026-09-07 21:07:34','2026-09-15 10:21:46'),(4,'Neurology','neurology','04','A focused portfolio across neurological care.','Onecore’s neurology portfolio includes prescription therapies and supportive formulations used across a range of neurological and neuro nutritional needs.','/uploads/neurology-1789467648173-506505903.jpg',4,1,NULL,NULL,'2026-09-07 21:07:34','2026-09-15 10:20:50'),(5,'Ophthalmology','ophthalmology','05','Specialised formulations for different areas of eye care.','Our ophthalmology range includes products used across ocular infection, inflammation, glaucoma related care, lubrication and other ophthalmic needs.','/uploads/opthalmology-1789467121099-139694507.jpg',5,1,NULL,NULL,'2026-09-07 21:07:34','2026-09-15 10:12:06'),(6,'Dermatology','dermatology','06','Formulations for medical and supportive skin care.','The dermatology portfolio spans prescription and supportive formulations across fungal infections, acne, inflammatory skin conditions, pigmentation and skin health.','/uploads/dermat-1789467587999-853611551.webp',6,1,NULL,NULL,'2026-09-07 21:07:34','2026-09-15 10:19:52'),(7,'ENT','ent','07','Focused support across ear, nose and throat care.','A portfolio developed around common and specialised needs encountered across ENT practice.','/uploads/ent-1789467302337-287607509.jpg',7,1,NULL,NULL,'2026-09-07 21:07:34','2026-09-15 10:15:06'),(8,'General Medicine','general-medicine','08','Everyday therapies across a broad range of clinical needs.','Our general medicine portfolio includes gastrointestinal care, anti infectives, pain management, allergy care and other commonly encountered therapeutic needs.','/assets/therapeutic-general-medicine.jpg',8,1,NULL,NULL,'2026-09-07 21:07:34','2026-09-07 21:07:34'),(9,'Oncology','oncology','09','Specialised therapies within cancer care.','Onecore’s oncology portfolio brings together specialised prescription products used across selected areas of cancer treatment and supportive care.','/uploads/oncology-1789467463153-137316380.jpg',9,1,NULL,NULL,'2026-09-07 21:07:34','2026-09-15 10:17:47');
